// Lazy panic argument formatting and static atomic Debug callback cells.
use def_id_reference::{*,DEF_ID_DEBUG};use serde_json::{Value,json};
use std::{cell::{RefCell,Cell},fmt,panic::{self,AssertUnwindSafe},io::{self,BufRead,Write}};
thread_local!{static EVENTS:RefCell<Vec<String>>=const{RefCell::new(Vec::new())};static QUERY:RefCell<Value>=const{RefCell::new(Value::Null)};static LIVE:Cell<bool>=const{Cell::new(false)};}
fn event(s:String){if LIVE.with(|v|v.get()){println!("EVENT\t{s}");io::stdout().flush().unwrap()};EVENTS.with(|v|v.borrow_mut().push(s))}
fn text(q:&Value,k:&str)->String{q[k].as_str().unwrap_or("").into()}
fn debug(_:DefId,f:&mut fmt::Formatter<'_>)->fmt::Result{event(format!("debug:panic={}",std::thread::panicking()));let mode=QUERY.with(|v|text(&v.borrow(),"debug"));match mode.as_str(){"error"=>Err(fmt::Error),"partial"=>{f.write_str("piece")?;Err(fmt::Error)},"panic"=>panic!("debug panic"),_=>f.write_str("custom")}}
fn first(_:DefId,f:&mut fmt::Formatter<'_>)->fmt::Result{event("first".into());DEF_ID_DEBUG.swap(&SECOND);f.write_str("first")}
fn second(_:DefId,f:&mut fmt::Formatter<'_>)->fmt::Result{event("second".into());f.write_str("second")}
static CUSTOM:fn(DefId,&mut fmt::Formatter<'_>)->fmt::Result=debug;static FIRST:fn(DefId,&mut fmt::Formatter<'_>)->fmt::Result=first;static SECOND:fn(DefId,&mut fmt::Formatter<'_>)->fmt::Result=second;
fn payload(e:Box<dyn std::any::Any+Send>)->String{if let Some(s)=e.downcast_ref::<String>(){s.clone()}else if let Some(s)=e.downcast_ref::<&str>(){(*s).into()}else{"opaque".into()}}
fn action(q:&Value){let local=q["local"].as_bool().unwrap_or(false);let id=DefId{krate:CrateNum::from_u32(if local{0}else{1}),index:DefIndex::from_u32(2)};let result=panic::catch_unwind(AssertUnwindSafe(||{if text(q,"op")=="format"{let result=if text(q,"debug")=="swap"{format!("{id:?}|{id:?}")}else{format!("{id:?}")};event("value:".to_owned()+&result)}else{event(format!("value:{}",id.expect_local().local_def_index.as_u32()))}}));match result{Ok(_)=>event("caught:false".into()),Err(e)=>{event("caught:true".into());event("payload:".to_owned()+&payload(e))}}}
struct Guard(Value);impl Drop for Guard{fn drop(&mut self){event(format!("inherited:panic={}",std::thread::panicking()));action(&self.0)}}
fn run(q:Value)->Value{QUERY.with(|v|*v.borrow_mut()=q.clone());EVENTS.with(|v|v.borrow_mut().clear());panic::set_hook(Box::new(|_|{}));let original=&*DEF_ID_DEBUG;let old=if text(&q,"debug")=="default"{original}else if text(&q,"debug")=="swap"{DEF_ID_DEBUG.swap(&FIRST)}else{DEF_ID_DEBUG.swap(&CUSTOM)};event(format!("original:{}",std::ptr::eq(original,old)));match text(&q,"context").as_str(){"inherited"=>{let _=panic::catch_unwind(AssertUnwindSafe(||{let _guard=Guard(q.clone());panic!("outer")}));event("outer-caught:true".into())},"processing"=>{let q=q.clone();panic::set_hook(Box::new(move |_|{event(format!("processing:panic={}",std::thread::panicking()));action(&q)}));let _=panic::catch_unwind(||panic!("outer"));event("outer-caught:true".into())},_=>action(&q)};DEF_ID_DEBUG.swap(old);event(format!("restored:{}",std::ptr::eq(&*DEF_ID_DEBUG,original)));json!({"request":q,"events":EVENTS.with(|v|v.borrow().clone())})}
fn main(){LIVE.with(|v|v.set(std::env::args().any(|s|s=="--live")));for line in io::stdin().lock().lines(){let q=serde_json::from_str(&line.unwrap()).unwrap();println!("{}",run(q))}}
